Issue: ungzipping buffer with trailing garbage throws error

Problem:
One site sends a gzipped html page and I try to ungzip page for further processing but zlib throws error `incorrect header check`. Error happens due to extra data after gzipped page. Yes, gzipped data is not valid, since have trailing data, but in other hand, browser eat that normally.

Minimal example:

``` javascript
var zlib = require('zlib')

// from test-zlib-from-gzip-with-trailing-garbage.js
bufOk = Buffer.concat([
    zlib.gzipSync("abc"),
    Buffer(10).fill(0)
]);

bufWrong = Buffer.concat([
    zlib.gzipSync("abc"),
    Buffer("\n \n\n\n\n \n")
]);

// wil not raise Error
console.log("bufOk:", zlib.gunzipSync(bufOk).toString());

// will raise Error('incorrect header check')
console.log("bufWrong:", zlib.gunzipSync(bufWrong).toString());
```

Also live example:

``` javascript
var req = require('request')
req.get('http://irsural.ru', {gzip: true}, (err, res, body) => {
    if (err != null) {
        console.log('Error:', err);
        return 
    }
    console.log(body);
});
```

After investigating the issue it _looks_ like that the error happens only when the `fd` that passes the worker to the master is closed before it is received in the master process. The following patch, that closes the `fd` only after receiving the `NODE_HANDLE_ACK` message fixes the issue for me.

``` diff
diff --git a/lib/internal/child_process.js b/lib/internal/child_process.js
index 789c29e..44a245e 100644
--- a/lib/internal/child_process.js
+++ b/lib/internal/child_process.js
@@ -96,8 +96,8 @@ const handleConversion = {

postSend: function(handle, options) {
       // Close the Socket handle after sending it
-      if (handle && !options.keepOpen)
-        handle.close();
+      //if (handle && !options.keepOpen)
+      //  global_handle = handle;
     },

got: function(message, handle, emit) {
@@ -465,6 +465,11 @@ function setupChannel(target, channel) {
   target.on('internalMessage', function(message, handle) {
     // Once acknowledged - continue sending handles.
     if (message.cmd === 'NODE_HANDLE_ACK') {
+      if (target._pending_handle) {
+        target._pending_handle.close();
+        target._pending_handle = null;
+      }
+
       assert(Array.isArray(target._handleQueue));
       var queue = target._handleQueue;
       target._handleQueue = null;
@@ -615,8 +620,13 @@ function setupChannel(target, channel) {
       req.oncomplete = function() {
         if (this.async === true)
           control.unref();
-        if (obj && obj.postSend)
+        if (obj && obj.postSend) {
           obj.postSend(handle, options);
+          if (handle && !options.keepOpen) {
+            assert(!target._pending_handle);
+            target._pending_handle = handle;
+          }
+        }
```

This seems strange to me as my understanding was that closing the file descriptor after sending it was safe (at least in my Linux box I have not been able to reproduce the same issue). Thoughts?

