import { compressGzipSync, decompressGzipSync } from 'node:zlib/iter';
const fh = await open('input.txt', 'r');
// Read as text (sync)
console.log(textSync(fh.pullSync({ autoClose: true })));
// Sync compress pipeline: file -> gzip -> file
