```mjs
const endpoint = await listen(callback, {
sni: {
'*': { keys: [defaultKey], certs: [defaultCert] },
'api.example.com': { keys: [apiKey], certs: [apiCert], port: 8443 },
'www.example.com': { keys: [wwwKey], certs: [wwwCert], ca: [customCA] },
